// ESP32 AUTO - sterowanie przez USB z telefonu
// Piny:
// P25 -> AIN1
// P26 -> AIN2
// P27 -> PWMA
// P32 -> BIN1
// P33 -> BIN2
// P14 -> PWMB
//
// Komendy z Serial USB Terminal:
// F = przod
// B = tyl
// L = skret lewo (krotki impuls)
// R = skret prawo (krotki impuls)
// C = zatrzymaj silnik skretu
// D = zatrzymaj naped
// S = STOP wszystkiego
//
// Predkosc portu: 115200 baud

const int AIN1 = 25;
const int AIN2 = 26;
const int PWMA = 27;

const int BIN1 = 32;
const int BIN2 = 33;
const int PWMB = 14;

// Bezpiecznik programowy: naped zatrzyma sie,
// jezeli przez 2 sekundy nie przyjdzie zadna komenda jazdy.
const unsigned long DRIVE_TIMEOUT_MS = 2000;

// Krotki impuls silnika skretu, aby nie trzymac go stale pod napieciem.
const unsigned long STEER_PULSE_MS = 180;

unsigned long lastDriveCommand = 0;
unsigned long steerStopAt = 0;
bool driveActive = false;
bool steerActive = false;

void stopDrive() {
  digitalWrite(AIN1, LOW);
  digitalWrite(AIN2, LOW);
  driveActive = false;
}

void forwardDrive() {
  digitalWrite(PWMA, HIGH);
  digitalWrite(AIN1, HIGH);
  digitalWrite(AIN2, LOW);
  lastDriveCommand = millis();
  driveActive = true;
}

void backwardDrive() {
  digitalWrite(PWMA, HIGH);
  digitalWrite(AIN1, LOW);
  digitalWrite(AIN2, HIGH);
  lastDriveCommand = millis();
  driveActive = true;
}

void stopSteering() {
  digitalWrite(BIN1, LOW);
  digitalWrite(BIN2, LOW);
  steerActive = false;
}

void steerLeft() {
  digitalWrite(PWMB, HIGH);
  digitalWrite(BIN1, HIGH);
  digitalWrite(BIN2, LOW);
  steerStopAt = millis() + STEER_PULSE_MS;
  steerActive = true;
}

void steerRight() {
  digitalWrite(PWMB, HIGH);
  digitalWrite(BIN1, LOW);
  digitalWrite(BIN2, HIGH);
  steerStopAt = millis() + STEER_PULSE_MS;
  steerActive = true;
}

void stopAll() {
  stopDrive();
  stopSteering();
}

void printHelp() {
  Serial.println();
  Serial.println("ESP32 AUTO GOTOWE");
  Serial.println("F = przod");
  Serial.println("B = tyl");
  Serial.println("L = lewo");
  Serial.println("R = prawo");
  Serial.println("C = stop skret");
  Serial.println("D = stop naped");
  Serial.println("S = STOP wszystko");
  Serial.println();
}

void setup() {
  pinMode(AIN1, OUTPUT);
  pinMode(AIN2, OUTPUT);
  pinMode(PWMA, OUTPUT);

  pinMode(BIN1, OUTPUT);
  pinMode(BIN2, OUTPUT);
  pinMode(PWMB, OUTPUT);

  digitalWrite(PWMA, HIGH);
  digitalWrite(PWMB, HIGH);

  stopAll();

  Serial.begin(115200);
  delay(500);
  printHelp();
}

void loop() {
  while (Serial.available() > 0) {
    char cmd = Serial.read();

    // ignoruj enter i spacje
    if (cmd == '\r' || cmd == '\n' || cmd == ' ') continue;

    // pozwol na male litery
    if (cmd >= 'a' && cmd <= 'z') cmd = cmd - 32;

    switch (cmd) {
      case 'F':
        forwardDrive();
        Serial.println("PRZOD");
        break;

      case 'B':
        backwardDrive();
        Serial.println("TYL");
        break;

      case 'L':
        steerLeft();
        Serial.println("LEWO");
        break;

      case 'R':
        steerRight();
        Serial.println("PRAWO");
        break;

      case 'C':
        stopSteering();
        Serial.println("STOP SKRET");
        break;

      case 'D':
        stopDrive();
        Serial.println("STOP NAPED");
        break;

      case 'S':
        stopAll();
        Serial.println("STOP");
        break;

      case '?':
        printHelp();
        break;

      default:
        Serial.print("Nieznana komenda: ");
        Serial.println(cmd);
        break;
    }
  }

  // automatyczne zatrzymanie skretu po krotkim impulsie
  if (steerActive && (long)(millis() - steerStopAt) >= 0) {
    stopSteering();
  }

  // awaryjne zatrzymanie napedu po braku komendy
  if (driveActive && millis() - lastDriveCommand > DRIVE_TIMEOUT_MS) {
    stopDrive();
    Serial.println("AUTO STOP - brak komendy");
  }
}
